@Test
public void testSymasDoc3SingleLine() throws Exception {
    SyncReplParser parser = new SyncReplParser();
    SyncRepl syncRepl = parser.parse("rid=123 " + "provider=ldap://provider.example.com:389 " + "type=refreshOnly " + "interval=01:00:00:00 " + "searchbase=\"dc=example,dc=com\" " + "filter=\"(objectClass=organizationalPerson)\" " + "scope=sub " + "attrs=\"cn,sn,ou,telephoneNumber,title,l\" " + "schemachecking=off " + "bindmethod=simple " + "binddn=\"cn=syncuser,dc=example,dc=com\" " + "credentials=secret");
