    (byte) 0xDB, (byte) 0x5F, //
    (byte) 0xB8, (byte) 0x7F, //
    (byte) 0x44, (byte) 0xBD, //
    (byte) 0x06, (byte) 0xE3, (byte) 0xA4, (byte) 0x09, (byte) 0x96, (byte) 0xA9, (byte) 0xA8 };
    String displayValue = editor.convertToString(bytes);
    //$NON-NLS-1$
    assertEquals(Strings.toLowerCaseAscii("{db78ba89-b85f-447f-bd06-e3a40996a9a8}"), displayValue);
}

