@ParameterizedTest
@LdapServersSource(mode = Mode.All)
public void testSimpleBindPlain(TestLdapServer ldapServer) {
    ldapServer.setConfidentialityRequired(false);
    StudioProgressMonitor monitor = getProgressMonitor();
