        pwdEditorBot.activateCurrentPasswordTab();
        pwdEditorBot.setVerifyPassword(generatedPassword);
        assertNull(pwdEditorBot.clickVerifyButton());
        assertNull(pwdEditorBot.clickBindButton());
        pwdEditorBot.clickCancelButton();
    }
}

